import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {applyParameterPreset,randomizeAdvanced} from './field-controls.mjs';
const html=await readFile(new URL('./index.html',import.meta.url),'utf8');for(const id of['advanced-randomize','preset-d-major','reverb','reverbSize'])assert.ok(html.includes('id="'+id+'"'),'actual UI control exists: '+id);
const preset=JSON.parse(await readFile(new URL('./presets/d-major-drift.json',import.meta.url),'utf8')),canonical=JSON.parse(await readFile(new URL('../presets/d-major-drift.json',import.meta.url),'utf8'));assert.deepEqual(preset,canonical);
const state={running:true,muted:true,phases:new Float32Array([.2,.5]),droneEnabled:true,sliders:{},choices:{}},originalPhases=state.phases;let depth=0;const adapter={begin(){depth++;},end(){depth--;},slider(name,value){state.sliders[name]=value;},choice(name,value){state.choices[name]=value;},toggle(name,value){state[name]=value;}};
applyParameterPreset(preset,adapter);assert.equal(depth,0);assert.equal(state.running,true);assert.equal(state.muted,true);assert.equal(state.phases,originalPhases);assert.equal(state.choices.root,73.416);assert.equal(state.choices.scale,'major');assert.equal(state.sliders.drift,2);assert.equal(state.sliders.reverb,0);assert.equal(state.choices.octaves,0);assert.equal(state.binaural,false);assert.equal(state.pulseEnabled,false);
state.droneEnabled=true;const sliderKeys=Object.keys(state.sliders),choiceKeys=Object.keys(state.choices);const choiceBefore={...state.choices},sliderBefore={...state.sliders};let n=0;const result=randomizeAdvanced(adapter,()=>[.4,.8][n++]);assert.ok(result.drift>=0&&result.drift<=2);assert.ok([-1,0,1].includes(result.projection));assert.equal(state.droneEnabled,true);assert.equal(state.running,true);assert.equal(state.phases,originalPhases);for(const key of sliderKeys)if(key!=='drift')assert.equal(state.sliders[key],sliderBefore[key]);for(const key of choiceKeys)if(key!=='projection')assert.equal(state.choices[key],choiceBefore[key]);assert.equal(depth,0);
console.log(JSON.stringify({ok:true,realControlsPresent:true,canonicalPresetExact:true,majorD2Recall:true,neutralLaterFeatures:true,presetPreservesTransportPhase:true,randomizesOnlyDriftProjection:true,bedPreserved:true},null,2));
